package org.racedaydreams.domain.strength;
import java.time.*;
import java.util.*;
/** Runner-requested edits create a new immutable version. They never change regular availability. */
public final class GymPlanEditor {
    private GymPlanEditor(){}
    public static GymProgramme move(GymProgramme original,String sessionId,LocalDate to,LocalDate today,Instant now,Set<LocalDate> completed){
        if(to==null||to.isBefore(today)||to.isBefore(original.start())||to.isAfter(original.end()))throw new IllegalArgumentException("Choose a future date inside this block.");
        for(var s:original.sessions())if(!s.id().equals(sessionId)&&s.date().equals(to))throw new IllegalArgumentException("Another strength session already uses this date.");
        return edit(original,sessionId,today,now,completed,"Runner moved one strength session; recurring days unchanged",s->new GymProgramme.Session(s.id(),to,s.title(),s.exercises(),s.explanation()));
    }
    public static GymProgramme skip(GymProgramme p,String id,LocalDate today,Instant now,Set<LocalDate> completed){return edit(p,id,today,now,completed,"Runner skipped one strength session; no catch-up volume",s->null);}
    public static GymProgramme reduce(GymProgramme p,String id,LocalDate today,Instant now,Set<LocalDate> completed){return edit(p,id,today,now,completed,"Runner reduced working sets for one session",s->{var exercises=new ArrayList<GymProgramme.Prescription>();for(var e:s.exercises())exercises.add(new GymProgramme.Prescription(e.exerciseId(),Math.max(1,e.sets()-1),e.minimumReps(),e.maximumReps(),e.seconds(),e.metres(),e.minimumRpe(),e.maximumRpe(),e.restSeconds(),e.intent(),e.referenceLoadKg()));return new GymProgramme.Session(s.id(),s.date(),s.title(),exercises,s.explanation());});}
    public static GymProgramme swap(GymProgramme p,String id,String exerciseId,String replacement,LocalDate today,Instant now,Set<LocalDate> completed){
        var from=ExerciseCatalog.definition(exerciseId);var to=ExerciseCatalog.definition(replacement);if(from==null||to==null||!from.category().equals(to.category())||from.exercise().region()!=to.exercise().region()||from.exercise().measurement()!=to.exercise().measurement()||!GymProgrammeGenerator.available(replacement,p.settings().equipment()))throw new IllegalArgumentException("Choose an available exercise with matching region and measurement.");
        return edit(p,id,today,now,completed,"Runner chose an exercise substitution",s->{var exercises=new ArrayList<GymProgramme.Prescription>();boolean found=false;for(var e:s.exercises()){if(e.exerciseId().equals(exerciseId)){found=true;exercises.add(new GymProgramme.Prescription(replacement,e.sets(),e.minimumReps(),e.maximumReps(),e.seconds(),e.metres(),e.minimumRpe(),e.maximumRpe(),e.restSeconds(),"Runner chose this alternative. "+e.intent(),null));}else exercises.add(e);}if(!found)throw new IllegalArgumentException("Exercise is not in this session.");return new GymProgramme.Session(s.id(),s.date(),s.title(),exercises,s.explanation());});
    }
    public static GymProgramme loadReference(GymProgramme p,String sessionId,String exerciseId,double kilograms,LocalDate today,Instant now,Set<LocalDate> completed){
        return edit(p,sessionId,today,now,completed,"Runner accepted an evidence-based load reference",s->{var exercises=new ArrayList<GymProgramme.Prescription>();boolean found=false;for(var e:s.exercises()){if(e.exerciseId().equals(exerciseId)){found=true;var definition=ExerciseCatalog.definition(exerciseId);if(definition==null||definition.exercise().measurement()!=StrengthExercise.MeasurementProfile.LOAD_REPS||e.referenceLoadKg()!=null&&kilograms<=e.referenceLoadKg())throw new IllegalArgumentException("Review a new, suitable load reference.");exercises.add(new GymProgramme.Prescription(e.exerciseId(),e.sets(),e.minimumReps(),e.maximumReps(),e.seconds(),e.metres(),e.minimumRpe(),e.maximumRpe(),e.restSeconds(),e.intent(),kilograms));}else exercises.add(e);}if(!found)throw new IllegalArgumentException("Exercise not prescribed.");return new GymProgramme.Session(s.id(),s.date(),s.title(),exercises,s.explanation());});
    }
    private interface Change {GymProgramme.Session apply(GymProgramme.Session s);}
    private static GymProgramme edit(GymProgramme p,String id,LocalDate today,Instant now,Set<LocalDate> completed,String reason,Change change){var sessions=new ArrayList<GymProgramme.Session>();boolean found=false;for(var s:p.sessions()){if(s.id().equals(id)){found=true;if(s.date().isBefore(today)||completed.contains(s.date()))throw new IllegalArgumentException("Completed or historical prescriptions cannot be rewritten.");var replacement=change.apply(s);if(replacement!=null)sessions.add(replacement);}else sessions.add(s);}if(!found)throw new IllegalArgumentException("Session not found.");return new GymProgramme(p.id(),p.version()+1,now,reason,p.settings(),p.start(),p.end(),sessions,p.tradeoffs());}
}
